// Words one loan for a status line: Dune, due 2030-01-15, 2 renewals left.
const titlePart = (loan) => loan.book.title;
const duePart = (loan) => loan.dueDate.slice(0, 10);
const leftPart = (loan) => loan.limits.renewals - loan.renewals;
const renewalsPart = (left) => `${left} renewal left`;

export function loanLine(loan) {
  const title = titlePart(loan);
  const due = duePart(loan);
  const left = leftPart(loan);
  return `${title}, due ${due}, ${renewalsPart(left)}`;
}
